<script setup>import {Head,usePage,router} from '@inertiajs/vue3';import {Wrench,MapPin,Phone} from 'lucide-vue-next';import {date} from '../lib/labels';defineProps({technicians:Array});const u=usePage().props.auth.user;</script><template><Head title="Techniciens"/><div class="page-heading"><span class="eyebrow">LES COMPÉTENCES AU PLUS PRÈS DU TERRAIN</span><h1>Techniciens référencés</h1><p>Trouvez les compétences nécessaires dans votre zone.</p></div><div class="grid three"><article class="card" v-for="t in technicians" :key="t.id"><div class="point-top"><span class="avatar large">{{t.user.name[0]}}</span><span :class="['badge',t.availability==='disponible'?'fonctionnel':'inconnu']">{{t.availability}}</span></div><h3>{{t.user.name}}</h3><p class="muted">{{t.referenced?'Référencé par la coordination':'Référencement en attente'}}</p><div class="tags"><span v-for="s in t.skills" :key="s">{{s}}</span></div><p class="location mt"><MapPin :size="15"/>{{t.zones.map(z=>z.name).join(', ')}}</p><p class="location"><Phone :size="15"/>{{t.phone}}</p><p class="muted">Mis à jour le {{date(t.updated_at)}}</p><label v-if="u.role==='admin'||u.id===t.user_id">Actualiser la disponibilité<select :value="t.availability" @change="router.post('/techniciens/'+t.id+'/disponibilite',{availability:$event.target.value})"><option value="disponible">Disponible</option><option value="occupe">Occupé</option><option value="indisponible">Indisponible</option></select></label></article></div><div v-if="!technicians.length" class="card empty">Aucun technicien référencé dans ce périmètre.</div></template>
